// Turns a round's runs into bench/results/<round>.md: mean and min-max per cell.

import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { JudgedRow } from "./judge.ts";
import { stepTotal } from "./metrics.ts";
import { loadChanges, REPO, RUNS, type StepRecord } from "./run.ts";

/** Everything above this line in an existing results file (the expectation) is kept. */
export const GENERATED_MARK =
  "<!-- generated by `pnpm bench summary`: edit above this line only -->";

const EXPECTATION_STUB = `## Expectation

Written before the round runs (EXPERIMENTS.md, rule 1): what is expected, and which decision the outcome drives.

TODO`;

export interface Loaded {
  chain: string;
  record: StepRecord;
}

/** The order a chain ran its steps: the draft, then the change requests in script order. */
function stepOrder(step: string): number {
  if (step === "e1") return 0;
  const i = loadChanges().findIndex((c) => `e2-${c.id}` === step);
  return i >= 0 ? i + 1 : Number.MAX_SAFE_INTEGER;
}

/**
 * Records written before the per-step cost fix hold the session's running total in `costUsd`
 * and `apiSeconds` and have no `sessionCostUsd`. Give them the per-step values, in step order.
 */
export function normalizeChain(records: StepRecord[]): StepRecord[] {
  const ordered = [...records].sort((a, b) => stepOrder(a.step) - stepOrder(b.step));
  let previous: { costUsd: number; apiSeconds: number } | undefined;
  return ordered.map((r) => {
    if (r.sessionCostUsd !== undefined) return r;
    const fixed = {
      ...r,
      sessionCostUsd: r.costUsd,
      sessionApiSeconds: r.apiSeconds,
      costUsd: stepTotal(r.costUsd, previous?.costUsd),
      apiSeconds: stepTotal(r.apiSeconds, previous?.apiSeconds),
    };
    previous = { costUsd: fixed.sessionCostUsd, apiSeconds: fixed.sessionApiSeconds };
    return fixed;
  });
}

export function loadRound(round: string): { runs: Loaded[]; baselines: StepRecord[] } {
  const root = join(RUNS, round);
  const runs: Loaded[] = [];
  const baselines: StepRecord[] = [];
  for (const chain of readdirSync(root).sort()) {
    const steps = join(root, chain, "steps");
    if (!existsSync(steps)) continue;
    const records: StepRecord[] = [];
    for (const step of readdirSync(steps).sort()) {
      const file = join(steps, step, "metrics.json");
      if (!existsSync(file)) continue;
      records.push(JSON.parse(readFileSync(file, "utf8")) as StepRecord);
    }
    for (const record of normalizeChain(records)) {
      if (record.arm === "baseline") baselines.push(record);
      else runs.push({ chain, record });
    }
  }
  return { runs, baselines };
}

/** `mean (min–max)`. */
export function stat(values: number[], digits = 2): string {
  if (values.length === 0) return "–";
  const mean = values.reduce((a, b) => a + b, 0) / values.length;
  const f = (n: number) => n.toFixed(digits);
  return `${f(mean)} (${f(Math.min(...values))}–${f(Math.max(...values))})`;
}

/** Judges' score of each picture, by `<chain>/<step>`: the sum of the judges' totals, out of 50. */
export function scoresByItem(round: string): Map<string, number> {
  const file = join(RUNS, round, "judging", "scores.json");
  const out = new Map<string, number>();
  if (!existsSync(file)) return out;
  const rows = JSON.parse(readFileSync(file, "utf8")) as JudgedRow[];
  const byItem = new Map<string, number[]>();
  for (const r of rows) {
    if (!r.verdict) continue;
    byItem.set(r.item, [...(byItem.get(r.item) ?? []), r.verdict.total]);
  }
  for (const [item, totals] of byItem) {
    if (totals.length >= 2)
      out.set(
        item,
        totals.reduce((a, b) => a + b, 0),
      );
  }
  return out;
}

/** Geometry defects in each picture, by `<chain>/<step>`, from `pnpm bench geometry` (benchmark 7). */
export function geometryByItem(round: string): Map<string, number> {
  const out = new Map<string, number>();
  const top = join(RUNS, round);
  if (!existsSync(top)) return out;
  for (const chain of readdirSync(top)) {
    const steps = join(top, chain, "steps");
    if (!existsSync(steps)) continue;
    for (const step of readdirSync(steps)) {
      const file = join(steps, step, "geometry.json");
      if (!existsSync(file)) continue;
      const g = JSON.parse(readFileSync(file, "utf8")) as { defects: unknown[]; error?: string };
      if (g.error === undefined) out.set(`${chain}/${step}`, g.defects.length);
    }
  }
  return out;
}

/** `mean (min–max)` of the known values, and how many are unknown (null). */
function nullable(values: (number | null)[]): string {
  const known = values.flatMap((v) => (v == null ? [] : [v]));
  const gap = values.length - known.length;
  return gap === 0 ? stat(known, 1) : `${stat(known, 1)}, ${gap} n/a`;
}

function groupBy<T>(xs: T[], key: (x: T) => string): Map<string, T[]> {
  const m = new Map<string, T[]>();
  for (const x of xs) m.set(key(x), [...(m.get(key(x)) ?? []), x]);
  return m;
}

export function buildTable(
  runs: Loaded[],
  scores: Map<string, number>,
  geometry: Map<string, number> = new Map(),
): string {
  const header = [
    "Step",
    "Arm",
    "Model",
    "Runs",
    "Cost ($)",
    "Wall (s)",
    "API (s)",
    "Turns",
    "Tool calls",
    "Fresh tokens",
    "Cache hit (%)",
    "Image reads",
    "Op errors (%)",
    "Denied",
    "Off-tool",
    "Engine defects",
    "Agent defects",
    "Geometry",
    "Picture",
    "Regens",
    "Score (/50)",
  ];
  const rows = [`| ${header.join(" | ")} |`, `|${header.map(() => "---").join("|")}|`];
  const cells = groupBy(runs, (r) => `${r.record.step}\t${r.record.arm}\t${r.record.modelAlias}`);
  for (const [key, group] of [...cells].sort(([a], [b]) => a.localeCompare(b))) {
    const [step, arm, model] = key.split("\t") as [string, string, string];
    const rs = group.map((g) => g.record);
    const failed = rs.filter((r) => r.isError || !r.finished).length;
    const opErr = rs.flatMap((r) => (r.grafical ? [r.grafical.rejectedShare * 100] : []));
    const sc = group.flatMap((g) => scores.get(`${g.chain}/${g.record.step}`) ?? []);
    rows.push(
      `| ${[
        step,
        arm,
        model,
        failed > 0 ? `${rs.length} (${failed} failed)` : String(rs.length),
        stat(
          rs.map((r) => r.costUsd),
          3,
        ),
        stat(
          rs.map((r) => r.wallSeconds),
          1,
        ),
        stat(
          rs.map((r) => r.apiSeconds),
          1,
        ),
        stat(
          rs.map((r) => r.turns),
          1,
        ),
        stat(
          rs.map((r) => r.toolCallTotal),
          1,
        ),
        stat(
          rs.map((r) => r.tokens.fresh),
          0,
        ),
        stat(
          rs.map((r) => r.tokens.cacheHitRate * 100),
          1,
        ),
        stat(
          rs.map((r) => r.imageReads),
          1,
        ),
        arm === "grafical" ? stat(opErr, 1) : "n/a",
        arm === "grafical"
          ? stat(
              rs.map((r) => r.grafical?.permissionDenials ?? 0),
              1,
            )
          : "n/a",
        arm === "grafical"
          ? stat(
              rs.map((r) => r.offTool ?? 0),
              1,
            )
          : "n/a",
        arm === "grafical" ? nullable(rs.map((r) => r.engineDefects)) : "n/a",
        arm === "grafical" ? nullable(rs.map((r) => r.agentDefects)) : "n/a",
        stat(
          group.flatMap((g) => geometry.get(`${g.chain}/${g.record.step}`) ?? []),
          1,
        ),
        `${rs.filter((r) => r.diagramPngUpdated).length}/${rs.length}`,
        stat(
          rs.map((r) => r.regenerations),
          1,
        ),
        stat(sc, 1),
      ].join(" | ")} |`,
    );
  }
  return rows.join("\n");
}

/** What a whole chain cost: the sum of its steps' own costs. */
export function buildChainTable(runs: Loaded[]): string {
  const lines = ["| Arm | Model | Chains | Chain cost ($) |", "|---|---|---|---|"];
  const byChain = groupBy(runs, (r) => r.chain);
  const cells = groupBy([...byChain.values()], (c) => {
    const r = (c[0] as Loaded).record;
    return `${r.arm}\t${r.modelAlias}`;
  });
  for (const [key, chains] of [...cells].sort(([a], [b]) => a.localeCompare(b))) {
    const [arm, model] = key.split("\t") as [string, string];
    const totals = chains.map((c) => c.reduce((sum, r) => sum + r.record.costUsd, 0));
    lines.push(`| ${arm} | ${model} | ${chains.length} | ${stat(totals, 3)} |`);
  }
  return lines.join("\n");
}

/** E1 numbers minus the empty run of the same model: cost and fresh tokens. */
export function buildNetTable(runs: Loaded[], baselines: StepRecord[]): string {
  const lines = ["| Arm | Model | Cost ($), net | Fresh tokens, net |", "|---|---|---|---|"];
  const cells = groupBy(
    runs.filter((r) => r.record.step === "e1"),
    (r) => `${r.record.arm}\t${r.record.modelAlias}`,
  );
  for (const [key, group] of [...cells].sort(([a], [b]) => a.localeCompare(b))) {
    const [arm, model] = key.split("\t") as [string, string];
    const base = baselines.find((b) => b.modelAlias === model);
    if (!base) continue;
    const rs = group.map((g) => g.record);
    lines.push(
      `| ${arm} | ${model} | ${stat(
        rs.map((r) => r.costUsd - base.costUsd),
        3,
      )} | ${stat(
        rs.map((r) => r.tokens.fresh - base.tokens.fresh),
        0,
      )} |`,
    );
  }
  return lines.join("\n");
}

export function failures(runs: Loaded[]): string[] {
  return runs
    .filter((r) => r.record.isError || !r.record.finished)
    .map(
      (r) =>
        `- ${r.chain}/${r.record.step}: ${r.record.subtype ?? "no result event"}, $${r.record.costUsd.toFixed(3)}`,
    );
}

export function buildReport(round: string): string {
  const { runs, baselines } = loadRound(round);
  const first = runs[0]?.record ?? baselines[0];
  const models = [
    ...new Set(
      [...runs, ...baselines.map((record) => ({ record }))].map(
        (r) => `${r.record.modelAlias} = ${r.record.model}`,
      ),
    ),
  ];
  const commits = [...new Set(runs.map((r) => r.record.graficalCommit))];
  const out = [
    `# Round ${round}`,
    "",
    "## Versions",
    "",
    `- Claude Code: ${first?.claudeVersion ?? "unknown"}`,
    `- Models: ${models.join(", ") || "unknown"}`,
    `- grafical commit: ${commits.join(", ") || "unknown"}`,
    "",
    "## Baseline (the empty task)",
    "",
    ...baselines.map(
      (b) =>
        `- ${b.modelAlias}: $${b.costUsd.toFixed(4)}, ${b.wallSeconds.toFixed(1)} s, ${b.tokens.cacheWrite} cache-write, ${b.tokens.cacheRead} cache-read, ${b.tokens.uncachedInput} uncached input, ${b.tokens.output} output tokens`,
    ),
    "",
    "## Results",
    "",
    "Each cell is `mean (min–max)` over its runs. Raw numbers include Claude Code's fixed overhead.",
    "",
    buildTable(runs, scoresByItem(round), geometryByItem(round)),
    "",
    "### Cost of a whole chain (sum of the steps)",
    "",
    buildChainTable(runs),
    "",
    "### Draft (e1) minus the empty baseline",
    "",
    buildNetTable(runs, baselines),
    "",
    "## Failed runs",
    "",
    ...(failures(runs).length > 0 ? failures(runs) : ["None."]),
  ];
  return out.join("\n");
}

/** The results file: the expectation (kept if the file exists), then the generated report. */
export function writeSummary(round: string): { path: string; text: string } {
  const path = join(REPO, "bench", "results", `${round}.md`);
  let top = EXPECTATION_STUB;
  if (existsSync(path)) {
    const old = readFileSync(path, "utf8");
    const at = old.indexOf(GENERATED_MARK);
    if (at >= 0) top = old.slice(0, at).trimEnd();
  }
  return { path, text: `${top}\n\n${GENERATED_MARK}\n\n${buildReport(round)}\n` };
}
